import React from 'react';
import { StatusBar } from 'expo-status-bar';
import { useFonts, Fraunces_400Regular, Fraunces_600SemiBold } from '@expo-google-fonts/fraunces';
import { Outfit_400Regular, Outfit_500Medium } from '@expo-google-fonts/outfit';
import { ActivityIndicator, ScrollView, StyleSheet, Text, TouchableOpacity, View } from 'react-native';
import { SUBJECTS, FEATURES } from './src/data';
import { colors, fonts, radius, space } from './src/theme';

export default function App() {
  const [fontsLoaded] = useFonts({
    Fraunces_400Regular,
    Fraunces_600SemiBold,
    Outfit_400Regular,
    Outfit_500Medium,
  });

  if (!fontsLoaded) {
    return (
      <View style={styles.loader}>
        <ActivityIndicator size="large" color={colors.teal} />
      </View>
    );
  }

  return (
    <View style={styles.container}>
      <StatusBar style="dark" />
      <ScrollView contentContainerStyle={styles.content} showsVerticalScrollIndicator={false}>
        <View style={styles.hero}>
          <View style={styles.badge}>
            <Text style={styles.badgeText}>ExamAI</Text>
          </View>
          <Text style={styles.title}>AI-powered exam prep for every major certification.</Text>
          <Text style={styles.subtitle}>
            Practice smarter with guided review, curated study materials, and instant AI tutoring.
          </Text>
          <TouchableOpacity style={styles.primaryButton}>
            <Text style={styles.primaryButtonText}>Start study session</Text>
          </TouchableOpacity>
        </View>

        <View style={styles.section}>
          <Text style={styles.sectionTitle}>Features</Text>
          {FEATURES.map((feature) => (
            <View key={feature.title} style={styles.featureCard}>
              <Text style={styles.featureIcon}>{feature.icon}</Text>
              <View style={styles.featureText}>
                <Text style={styles.featureTitle}>{feature.title}</Text>
                <Text style={styles.featureBody}>{feature.body}</Text>
              </View>
            </View>
          ))}
        </View>

        <View style={styles.section}>
          <View style={styles.sectionHeader}>
            <Text style={styles.sectionTitle}>Subjects</Text>
            <TouchableOpacity style={styles.linkButton}>
              <Text style={styles.linkButtonText}>View all</Text>
            </TouchableOpacity>
          </View>
          {SUBJECTS.map((subject) => (
            <View key={subject.code} style={[styles.subjectCard, { borderColor: subject.color }]}> 
              <View style={[styles.subjectPill, { backgroundColor: subject.color }]}> 
                <Text style={styles.subjectCode}>{subject.code}</Text>
              </View>
              <Text style={styles.subjectLabel}>{subject.label}</Text>
              <Text style={styles.subjectCount}>{subject.count}</Text>
            </View>
          ))}
        </View>
      </ScrollView>
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: colors.bg,
  },
  content: {
    padding: space.lg,
    paddingBottom: space.xxl,
  },
  loader: {
    flex: 1,
    justifyContent: 'center',
    alignItems: 'center',
    backgroundColor: colors.bg,
  },
  hero: {
    marginBottom: space.xl,
    padding: space.lg,
    borderRadius: radius.lg,
    backgroundColor: colors.card,
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 8 },
    shadowOpacity: 0.08,
    shadowRadius: 20,
    elevation: 4,
  },
  badge: {
    alignSelf: 'flex-start',
    paddingHorizontal: space.md,
    paddingVertical: space.xs,
    borderRadius: radius.full,
    backgroundColor: colors.teal,
    marginBottom: space.sm,
  },
  badgeText: {
    color: colors.card,
    fontFamily: fonts.bodyMedium,
    fontSize: 12,
  },
  title: {
    color: colors.ink,
    fontFamily: fonts.displaySemiBold,
    fontSize: 32,
    lineHeight: 40,
    marginBottom: space.md,
  },
  subtitle: {
    color: colors.muted,
    fontFamily: fonts.body,
    fontSize: 16,
    lineHeight: 24,
    marginBottom: space.lg,
  },
  primaryButton: {
    backgroundColor: colors.teal,
    borderRadius: radius.md,
    paddingVertical: space.md,
    alignItems: 'center',
  },
  primaryButtonText: {
    color: colors.card,
    fontFamily: fonts.bodyMedium,
    fontSize: 16,
  },
  section: {
    marginBottom: space.xl,
  },
  sectionHeader: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: space.md,
  },
  sectionTitle: {
    color: colors.ink,
    fontFamily: fonts.displaySemiBold,
    fontSize: 20,
  },
  featureCard: {
    flexDirection: 'row',
    padding: space.md,
    backgroundColor: colors.card,
    borderRadius: radius.lg,
    marginBottom: space.sm,
  },
  featureIcon: {
    fontSize: 22,
    marginRight: space.md,
    color: colors.teal,
  },
  featureText: {
    flex: 1,
  },
  featureTitle: {
    color: colors.ink,
    fontFamily: fonts.bodyMedium,
    fontSize: 16,
    marginBottom: 4,
  },
  featureBody: {
    color: colors.muted,
    fontFamily: fonts.body,
    fontSize: 14,
    lineHeight: 20,
  },
  linkButton: {
    paddingHorizontal: space.sm,
    paddingVertical: space.xs,
  },
  linkButtonText: {
    color: colors.teal,
    fontFamily: fonts.bodyMedium,
    fontSize: 14,
  },
  subjectCard: {
    padding: space.md,
    borderRadius: radius.lg,
    backgroundColor: colors.card,
    borderWidth: 1,
    marginBottom: space.sm,
  },
  subjectPill: {
    alignSelf: 'flex-start',
    paddingHorizontal: space.sm,
    paddingVertical: 4,
    borderRadius: radius.full,
    marginBottom: space.sm,
  },
  subjectCode: {
    color: colors.card,
    fontFamily: fonts.bodyMedium,
    fontSize: 12,
  },
  subjectLabel: {
    color: colors.ink,
    fontFamily: fonts.bodyMedium,
    fontSize: 16,
    marginBottom: 4,
  },
  subjectCount: {
    color: colors.muted,
    fontFamily: fonts.body,
    fontSize: 14,
  },
});
